const nights = Number(vars.stay_nights || 0);
const subtotal = Number(vars.selected_room_nightly_rate_minor || 0) * nights * Number(vars.rooms_requested || 1);
const taxes = Number(vars.selected_room_tax_amount_minor || 0);
